begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)
select ('a9000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated',case i when 2 then 'invited@example.test' else 'invite-test-'||i||'@example.test' end,'',now(),now(),now() from generate_series(1,3)i;
insert into public.platform_operators(user_id,role,full_name,email) values
 ('a9000000-0000-4000-8000-000000000001','owner','Emissor sintético','invite-test-1@example.test'),
 ('a9000000-0000-4000-8000-000000000003','owner','Outro operador sintético','invite-test-3@example.test');
insert into public.organizations(id,name,slug,status) values('b9000000-0000-4000-8000-000000000001','Convite sintético','invite-security','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values('c9000000-0000-4000-8000-000000000001','b9000000-0000-4000-8000-000000000001','Sede','sede','headquarters');
insert into public.saas_organization_invites(id,organization_id,owner_name,owner_email,invite_token,created_by)
values('e9000000-0000-4000-8000-000000000001','b9000000-0000-4000-8000-000000000001','Pessoa convidada','invited@example.test','f9000000-0000-4000-8000-000000000001','a9000000-0000-4000-8000-000000000001');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a9000000-0000-4000-8000-000000000003","email":"invited@example.test","role":"authenticated"}',true);
select throws_ok($$select public.accept_organization_invite('f9000000-0000-4000-8000-000000000001')$$,'42501','invite_email_mismatch','JWT de outra conta não fabrica e-mail convidado');
select is(public.pending_organization_invitation(),null::jsonb,'outra conta não descobre convite pelo e-mail do JWT');
select set_config('request.jwt.claims','{"sub":"a9000000-0000-4000-8000-000000000002","email":"stale@example.test","role":"authenticated"}',true);
select is(public.pending_organization_invitation()->>'token','f9000000-0000-4000-8000-000000000001','descoberta usa e-mail atual e confirmado do banco');
reset role;
update auth.users set email_confirmed_at=null where id='a9000000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.accept_organization_invite('f9000000-0000-4000-8000-000000000001')$$,'42501','confirmed_email_required','e-mail não confirmado não assume ministério');
select is(public.pending_organization_invitation(),null::jsonb,'não confirmado não recebe token por descoberta');
reset role;
update auth.users set email_confirmed_at=now(),email='changed@example.test' where id='a9000000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.accept_organization_invite('f9000000-0000-4000-8000-000000000001')$$,'42501','invite_email_mismatch','mudança de e-mail invalida a correspondência antiga');
reset role;
update auth.users set email='invited@example.test' where id='a9000000-0000-4000-8000-000000000002';
set local role authenticated;
select is((public.accept_organization_invite('f9000000-0000-4000-8000-000000000001')->>'alreadyAccepted')::boolean,false,'primeiro aceite cria vínculo autorizado');
select is((select count(*) from public.organization_memberships where organization_id='b9000000-0000-4000-8000-000000000001'),1::bigint,'uma única participação criada');
select is((public.accept_organization_invite('f9000000-0000-4000-8000-000000000001')->>'alreadyAccepted')::boolean,true,'repetição retoma acesso sem nova concessão');
select is((select count(*) from public.organization_membership_events where organization_id='b9000000-0000-4000-8000-000000000001'),1::bigint,'repetição não duplica evento nem participação');
reset role;
select is((select accepted_user_id from public.saas_organization_invites where id='e9000000-0000-4000-8000-000000000001'),'a9000000-0000-4000-8000-000000000002'::uuid,'aceite fica vinculado à identidade, não só ao e-mail');
update public.organization_memberships set role='leader' where organization_id='b9000000-0000-4000-8000-000000000001';
set local role authenticated;
select lives_ok($$select public.accept_organization_invite('f9000000-0000-4000-8000-000000000001')$$,'mesma conta ativa pode retomar sem promover papel');
select is((select role::text from public.organization_memberships where organization_id='b9000000-0000-4000-8000-000000000001'),'leader','retomada não restaura antigo papel owner');
reset role;
update public.organization_memberships set status='suspended' where organization_id='b9000000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.accept_organization_invite('f9000000-0000-4000-8000-000000000001')$$,'42501','invite_access_revoked','aceito não reativa vínculo suspenso');
reset role;
update public.organization_memberships set role='owner',status='active' where organization_id='b9000000-0000-4000-8000-000000000001';
update public.saas_organization_invites set status='pending',accepted_at=null,accepted_user_id=null where id='e9000000-0000-4000-8000-000000000001';
update public.organization_memberships set role='secretary' where organization_id='b9000000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.accept_organization_invite('f9000000-0000-4000-8000-000000000001')$$,'42501','invite_existing_membership','pendente não promove participação existente');
select is(public.pending_organization_invitation(),null::jsonb,'descoberta não oferece convite que elevaria vínculo existente');
reset role;
update public.organization_memberships set role='owner' where organization_id='b9000000-0000-4000-8000-000000000001';
update public.platform_operators set active=false where user_id='a9000000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.accept_organization_invite('f9000000-0000-4000-8000-000000000001')$$,'42501','invite_issuer_unavailable','emissor suspenso não concede propriedade');
reset role;
update public.platform_operators set active=true where user_id='a9000000-0000-4000-8000-000000000001';
update public.saas_organization_invites set expires_at=now()-interval '1 day' where id='e9000000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.accept_organization_invite('f9000000-0000-4000-8000-000000000001')$$,'22023','invite_expired','prazo vencido não concede acesso');
reset role;
update public.saas_organization_invites set status='revoked' where id='e9000000-0000-4000-8000-000000000001';
set local role anon;
select is(public.organization_invite_preview('f9000000-0000-4000-8000-000000000001')->>'ownerName','','revogado não revela nome do convidado');
select is(public.organization_invite_preview('f9000000-0000-4000-8000-000000000001')->>'ownerEmail','','revogado não revela e-mail do convidado');
reset role;
update public.organizations set status='suspended' where id='b9000000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.accept_organization_invite('f9000000-0000-4000-8000-000000000001')$$,'42501','invite_unavailable','ministério suspenso não é reativado por convite');
select throws_ok($$select public.organization_invite_preview('f9000000-0000-4000-8000-000000000001')$$,'P0002','invite_unavailable','prévia não apresenta ministério suspenso');
reset role;
select * from finish();
rollback;
